package com.markethub.seller.application;
import java.math.BigDecimal; import java.time.*; import java.time.ZoneOffset; import java.util.*;
import com.markethub.orders.infrastructure.jpa.SellerOrderRepository; import com.markethub.seller.domain.SellerStatus; import com.markethub.seller.infrastructure.jpa.*;
import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
@Service public class SellerSettlementService{
 private static final List<String> PAID=List.of("DELIVERED"); private final SellerRepository sellers;private final SellerSettlementRepository settlements;private final SellerOrderRepository orders;private final Clock clock;
 public SellerSettlementService(SellerRepository sellers,SellerSettlementRepository settlements,SellerOrderRepository orders,Clock clock){this.sellers=sellers;this.settlements=settlements;this.orders=orders;this.clock=clock;}
 @Transactional(readOnly=true) public List<SettlementView> own(Long userId){var seller=sellers.findByUserId(userId).filter(s->s.getStatus()==SellerStatus.APPROVED).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Approved seller access is required"));return settlements.findAllBySeller_User_IdOrderByCreatedAtDesc(userId).stream().map(SettlementView::from).toList();}
 @Transactional(readOnly=true) public List<SettlementView> adminList(){return settlements.findAllByOrderByCreatedAtDesc().stream().map(SettlementView::from).toList();}
 @Transactional public SettlementView create(Long sellerId,LocalDate from,LocalDate to){if(from==null||to==null||to.isBefore(from)||to.isAfter(LocalDate.now(clock))||to.toEpochDay()-from.toEpochDay()>365)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a valid settlement period of up to 366 days");var seller=sellers.findById(sellerId).filter(s->s.getStatus()==SellerStatus.APPROVED).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Approved seller was not found"));if(settlements.existsOverlappingPeriod(sellerId,from,to))throw new ResponseStatusException(HttpStatus.CONFLICT,"A settlement already covers part of this period");var rows=orders.findAllBySeller_User_IdAndCreatedAtGreaterThanEqualAndCreatedAtLessThan(seller.getUser().getId(),from.atStartOfDay().toInstant(ZoneOffset.UTC),to.plusDays(1).atStartOfDay().toInstant(ZoneOffset.UTC)).stream().filter(r->PAID.contains(r.getStatus())&&"PAID".equals(r.getOrder().getPaymentStatus())&&!"REFUNDED".equals(r.getOrder().getStatus())).toList();if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"No eligible delivered paid sales were found for this period");String currency=rows.getFirst().getOrder().getCurrency();if(rows.stream().anyMatch(r->!currency.equals(r.getOrder().getCurrency())))throw new ResponseStatusException(HttpStatus.CONFLICT,"A settlement period cannot contain multiple currencies");BigDecimal gross=rows.stream().map(r->r.getSubtotal()).reduce(BigDecimal.ZERO,BigDecimal::add),commission=rows.stream().map(r->r.getCommission()).reduce(BigDecimal.ZERO,BigDecimal::add);return SettlementView.from(settlements.save(new SellerSettlementEntity(seller,from,to,gross,commission,gross.subtract(commission),currency)));}
 @Transactional public SettlementView markPaid(Long id,String reference){var row=settlements.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Settlement was not found"));try{row.markPaid(reference.trim());}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}return SettlementView.from(row);}
 public record SettlementView(Long id,Long sellerId,String businessName,LocalDate periodFrom,LocalDate periodTo,BigDecimal grossAmount,BigDecimal commissionAmount,BigDecimal netAmount,String currency,String status,String payoutReference,Instant paidAt,Instant createdAt){static SettlementView from(SellerSettlementEntity e){return new SettlementView(e.getId(),e.getSellerId(),e.getBusinessName(),e.getPeriodFrom(),e.getPeriodTo(),e.getGrossAmount(),e.getCommissionAmount(),e.getNetAmount(),e.getCurrency(),e.getStatus(),e.getPayoutReference(),e.getPaidAt(),e.getCreatedAt());}}
}
